static uintptr_t current_rd_idx;

static void validate_packet(struct test_data_var *packet)
{
	zassert_equal((uintptr_t)packet->hdr.data, current_rd_idx,
			"Got %x, expected: %x",
			(uint32_t)packet->hdr.data, (uint32_t)current_rd_idx);
	current_rd_idx++;
}

static void consistent_drop(const struct mpsc_pbuf_buffer *buffer,
			    const union mpsc_pbuf_generic *item)
{
	validate_packet((struct test_data_var *)item);
}

uint32_t rand_get(uint32_t min, uint32_t max)
{
	return min + (sys_rand32_get() % max);
}

ZTEST(log_buffer, test_overwrite_consistency)
{
	struct mpsc_pbuf_buffer buffer;
	static struct mpsc_pbuf_buffer_config cfg = {
		.buf = buf32,
		.size = ARRAY_SIZE(buf32),
		.notify_drop = consistent_drop,
		.get_wlen = get_wlen,
		.flags = MPSC_PBUF_MODE_OVERWRITE
	};

	mpsc_pbuf_init(&buffer, &cfg);
	int repeat = 50000;
	int id = 0;

	while (id < repeat) {
		struct test_data_var *tdv = NULL;
		bool alloc_during_claim = (rand_get(1, 5) <= 2);

		/* Occasionally claim buffer to simulate that claiming is
		 * interrupted by allocation.
		 */
		if (alloc_during_claim) {
			tdv = (struct test_data_var *)mpsc_pbuf_claim(&buffer);
			if (tdv) {
				validate_packet(tdv);
			}
		}

		uint32_t wr_cnt = rand_get(1, 15);

		for (int i = 0; i < wr_cnt; i++) {
			uint32_t wlen = rand_get(1, 15);
			struct test_data_var *tdv2;

			tdv2 = (struct test_data_var *)mpsc_pbuf_alloc(&buffer,
								       wlen,
								       K_NO_WAIT);
			tdv2->hdr.len = wlen;
			tdv2->hdr.data = id++;
			mpsc_pbuf_commit(&buffer, (union mpsc_pbuf_generic *)tdv2);
		}

		/* Put back item claimed before committing new items. */
		if (tdv) {
			mpsc_pbuf_free(&buffer, (union mpsc_pbuf_generic *)tdv);
		}

		uint32_t rd_cnt = rand_get(1, 30);

		for (int i = 0; i < rd_cnt; i++) {
			struct test_data_var *tdv2;

			tdv2 = (struct test_data_var *)mpsc_pbuf_claim(&buffer);
			if (!tdv2) {
				continue;
			}

			validate_packet(tdv2);
			mpsc_pbuf_free(&buffer, (union mpsc_pbuf_generic *)tdv2);
		}
	}
}

K_THREAD_STACK_DEFINE(t1_stack, 1024);
K_THREAD_STACK_DEFINE(t2_stack, 1024);

static k_thread_stack_t *stacks[2] = {t1_stack, t2_stack};
static struct k_thread threads[2];
static k_tid_t tids[2];

void t_entry(void *p0, void *p1, void *p2)
{
	struct mpsc_pbuf_buffer *buffer = p0;
	uintptr_t wait_ms = (uintptr_t)p1;
	struct test_data_ext *t;
	void *vt;

	t = (struct test_data_ext *)mpsc_pbuf_alloc(buffer,
						    sizeof(*t) / sizeof(uint32_t),
						    K_MSEC(1));
	zassert_is_null(t);

	t = (struct test_data_ext *)mpsc_pbuf_alloc(buffer,
						    sizeof(*t) / sizeof(uint32_t),
						    K_MSEC(wait_ms));
	t->hdr.len = PUT_EXT_LEN;
	t->data = k_current_get();

	vt = t;
	zassert_true(IS_PTR_ALIGNED(vt, union mpsc_pbuf_generic), "unaligned ptr");
	mpsc_pbuf_commit(buffer, (union mpsc_pbuf_generic *)vt);
	while (1) {
		k_sleep(K_MSEC(10));
	}
}

void start_threads(struct mpsc_pbuf_buffer *buffer)
{
	int prio = 2;
	uintptr_t wait_ms = 1000;

	for (int i = 0; i < ARRAY_SIZE(threads); i++) {
		tids[i] = k_thread_create(&threads[i], stacks[i], 1024, t_entry,
					  buffer, (void *)wait_ms, NULL,
					  prio--,
					  0, K_NO_WAIT);
	}

	k_sleep(K_MSEC(10));

	for (int i = 0; i < ARRAY_SIZE(threads); i++) {
		k_ticks_t t = k_thread_timeout_remaining_ticks(tids[i]);
		k_ticks_t exp_wait = k_ms_to_ticks_ceil32(wait_ms);

		/* Threads shall be blocked, waiting for available space. */
		zassert_within(t, exp_wait, k_ms_to_ticks_ceil32(20));
	}
}

static uint32_t buf32_1[128];
struct test_msg_data {
	union mpsc_pbuf_generic hdr;
	uint32_t buf_len; /*contain buf_len and buf*/
	uint8_t buf[sizeof(buf32_1)];
};
struct test_msg_hnd {
	struct mpsc_pbuf_buffer mpsc_buffer;
	uint32_t product_max_cnt;
	uint32_t product_cnt;
	uint32_t consumer_cnt;
};

K_THREAD_STACK_DEFINE(t3_stack, 1024);
static struct k_thread threads_t3;
static k_tid_t tid3;

static uint32_t test_mpsc_get_used_len(const union mpsc_pbuf_generic *packet)
{
	uint32_t size = 0;
	struct test_msg_data *msg_data = NULL;

	msg_data =  CONTAINER_OF(packet, struct test_msg_data, hdr);
	size = msg_data->buf_len + sizeof(union mpsc_pbuf_generic);
	size = ROUND_UP(size, sizeof(uint32_t)); /*return number  of uint32_t */
	size = size / sizeof(uint32_t);
	return size;
}

static void t_data_consumer_entry(void *p0, void *p1, void *p2)
{
	uint32_t read_cnt = 0;
	bool wait = true;
	const union mpsc_pbuf_generic *msg = NULL;
	const struct test_msg_data *test_data = NULL;
	struct test_msg_hnd *test_hnd = (struct test_msg_hnd *)p0;

	while (1) {
		if (msg == NULL) {
			msg = mpsc_pbuf_claim(&test_hnd->mpsc_buffer);
		}
		test_data = (const struct test_msg_data *)msg;
		if (test_data == NULL) {
			continue;
		}
		if (test_data && test_hnd->mpsc_buffer.wr_idx == 0) {
			wait = false;
		}
		if (wait == true) {
			continue;
		}
		read_cnt++;
		mpsc_pbuf_free(&test_hnd->mpsc_buffer, msg);
		msg = NULL;
		if (read_cnt == test_hnd->product_max_cnt) {
			break;
		}

	}
	test_hnd->consumer_cnt = read_cnt;
}

/* test mpsc_pbuf_alloc can get sem_take
 * one thread product data, one thread consumer data
 * requirement:
 *      consumer slow process data
 * step:
 *  1:product data len is  0.75 of cfg.size
 *  2:run product times
 *
 */
ZTEST(log_buffer, test_sema_lock)
{
	struct test_msg_hnd  test_hnd = {};
	struct test_msg_data  test_data;
	struct test_msg_data  *item = NULL;
	struct mpsc_pbuf_buffer_config  cfg;
	uint32_t loop = 0;
	size_t wlen = 0;
	bool fist_wait = true;

	if (CONFIG_SYS_CLOCK_TICKS_PER_SEC < 10000) {
		ztest_test_skip();
	}

	cfg.buf = buf32_1;
	cfg.size = ARRAY_SIZE(buf32_1);
	cfg.get_wlen = test_mpsc_get_used_len;

	mpsc_pbuf_init(&test_hnd.mpsc_buffer, &cfg);
	test_hnd.product_max_cnt = 2;

	tid3 = k_thread_create(&threads_t3, t3_stack, 1024,
			t_data_consumer_entry,
			&test_hnd, NULL, NULL,
			10, 0, K_NO_WAIT);
	k_thread_name_set(&threads_t3, "test_mpsc_consumer");
	for (loop = 0; loop < test_hnd.product_max_cnt; loop++) {
		if (loop == 0) {
			test_data.buf_len = sizeof(buf32_1) / 2;
		} else {
			test_data.buf_len = sizeof(buf32_1) / 2 + sizeof(buf32_1) / 4;
		}
		test_data.buf_len = ROUND_UP(test_data.buf_len, sizeof(uint32_t));
		memset(test_data.buf, loop + 1, test_data.buf_len);

		wlen = test_data.buf_len + sizeof(test_data.buf_len) +
			 sizeof(test_data.hdr);
		wlen = ROUND_UP(wlen, sizeof(uint32_t));
		wlen = wlen / sizeof(uint32_t);

		if (fist_wait &&
		   test_data.buf_len == sizeof(buf32_1) / 2 + sizeof(buf32_1) / 4) {
			PRINT(" mpsc sema wait\n");
		}
		item = (struct test_msg_data *)mpsc_pbuf_alloc(&test_hnd.mpsc_buffer,
								wlen, K_FOREVER);
		item->hdr.raw = 0;
		memcpy(item->buf, test_data.buf, test_data.buf_len);
		item->buf_len = test_data.buf_len + sizeof(test_data.buf_len);
		mpsc_pbuf_commit(&test_hnd.mpsc_buffer, &item->hdr);
		if (fist_wait &&
		    test_data.buf_len == sizeof(buf32_1) / 2 + sizeof(buf32_1) / 4) {
			PRINT(" mpsc sema wake\n");
			fist_wait = false;
		}
		test_hnd.product_cnt++;
	}
	k_thread_join(tid3, K_FOREVER);
	zassert_equal(test_hnd.product_cnt,
		      test_hnd.consumer_cnt, "product %d consume %d",
		      test_hnd.product_cnt, test_hnd.consumer_cnt);

}
